import{_ as t,c as o,b as r,o as n}from"./app-DyGkStdA.js";const s={};function l(a,e){return n(),o("div",null,e[0]||(e[0]=[r('<p>Here is the solution to allow them to sync their Shopify store products with your Shopify store. &quot;Create an app for your sellers&quot; by enabling the Seller Shopify store Connector feature app.</p><p>If your sellers also have Shopify stores and they want to add products from their respective stores to the Admin Shopify Store</p><p>then you can use Seller Shopify store connector featured app of the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace app</a>.</p><p>You can get this featured app at a monthly subscription of $ 40 (USD) over &amp; above your current multivendor app plan.</p><h3 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h3><ul><li>Let the marketplace sellers sync their Shopify store products with the admin&#39;s Shopify store.</li><li>Also, Seller’s Shopify store’s inventory will be synced with the admin Shopify store.</li><li>Further, the seller needs to create a private app on his Shopify store and configure the details in his/her seller panel.</li><li>Order &amp; inventory will be synced on both admin &amp; seller Shopify end.</li><li>Moreover, sellers can now update products in bulk from the “products” section of the seller app.</li><li>The sellers can register webbooks on their own based on their permission.</li><li>Compatible with the <strong><a href="https://webkul.com/blog/shopify-multivendor-marketplace-partial-fulfillment/" target="_blank" rel="noopener noreferrer">Partial Fulfillment</a></strong> feature.</li><li>Smart collections can now be imported from the seller Shopify store into the Multi-vendor app via this Seller Shopify store connector add-on. <a href="https://webkul.com/blog/shopify-multivendor-marketplace-collection-sync-from-shopify-store/" target="_blank" rel="noopener noreferrer">Know About Collection Sync Process</a></li><li>Tags can be mapped via CSV file upload.</li></ul><p>Check the below video for the Seller Shopify Store Connector:</p><p>0wTN1sLpD78</p><h3 id="activate-the-feature-app" tabindex="-1"><a class="header-anchor" href="#activate-the-feature-app"><span>Activate the Feature App</span></a></h3><p>To get this feature app, go to the Feature App section &amp; get the &quot;Seller Shopify store connector&quot; feature app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Screenshot-96.png" alt="Screenshot-96"></p><p>Click the <strong>Enable</strong> button to activate the <strong>Seller Shopify Store Connector</strong> feature app.</p><p>Approve the charge &amp; get the feature to your marketplace.</p><p>Now, as soon as the Seller Shopify Connector feature app is Active, the sellers will get a new menu to the configuration menu of their respective Seller panels .</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Dashboard-Seller-•-Multivendor-MarketPlace-1200x627.png" alt="Dashboard-Seller-•-Multivendor-MarketPlace"></p><h3 id="new-workflow" tabindex="-1"><a class="header-anchor" href="#new-workflow"><span>NEW WORKFLOW :</span></a></h3><p>To make the product sync features work, the seller firstly needs to create a custom app on their Shopify store.</p><p>Step 1: The seller needs to log in to their Shopify account and create a custom app from the &quot;apps&quot; section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_37_35-1200x581.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_37_35"></p><p>Step 2: Click on &quot;create an app&quot; and enter the name of the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_40_42-1200x581.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_40_42"></p><p>After entering the name of the app, click on &quot;Create app&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_44_40.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_44_40"></p><p>Step 3: After creating the custom app, now the seller needs to configure Admin APIs by clicking on &quot;configure Admin API scopes&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_49_55-1200x581.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-11_49_55"></p><p>Now, the seller needs to provide the required permission for the custom app.</p><p><strong>Mandatory Permission to create custom app as sales channel:</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/permissions.png" alt="permissions"></p><h3 id="required-permissions-for-custom-app" tabindex="-1"><a class="header-anchor" href="#required-permissions-for-custom-app"><span>REQUIRED PERMISSIONS FOR CUSTOM APP</span></a></h3><p><strong>Here are the required permissions for the custom seller app</strong>:</p><p>Assigned fulfillment orders _(<strong>Read and write</strong>)<br> _# <code>write_assigned_fulfillment_orders</code> , <code>read_assigned_fulfillment_orders</code></p><p>Fulfillment services _(<strong>Read and write</strong>)<br> _# read_fulfillments, write_fulfillments</p><p>Inventory _(<strong>Read and write</strong>)<br> _# read_inventory, write_inventory</p><p>Locations _(<strong>Read Access</strong>)<br> _# read_locations</p><p>Order Editing _(<strong>Read and write</strong>)<br> _# read_orders, write_orders<br> Allow this permission if you want to sync the order details with the seller store once edited on the merchant&#39;s store, else don&#39;t allow it.</p><p>Orders _(<strong>Read and write</strong>)<br> _# read_orders, write_orders</p><p>Products <em><strong>(Read and write)</strong></em><br> # read_products, write_product</p><p>Markets<br> # <strong>read_merkets_home</strong></p><h3 id="required-permission-for-sales-channel-configuration" tabindex="-1"><a class="header-anchor" href="#required-permission-for-sales-channel-configuration"><span>Required Permission for Sales Channel Configuration</span></a></h3><p>#write_product_listings, #read_product_listings</p><p><strong>Storefront API access scopes</strong>:<br> #<code>unauthenticated_read_product_listings</code></p><p><em>Note: These permissions are mandatory for Sales Channel Configuration.</em></p><p>After providing the required permission, click on save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_06_39-823x1024.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_06_39"></p><p>Once, the permissions are saved, the seller will get an option to install the custom app.</p><p>The seller needs to install the app by clicking on the &quot;install app&quot; button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_13_09-1200x581.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_13_09"></p><p>Step 4: After installing the app, the seller will get the access token, API key, and secret key.</p><p>Now, the seller needs to copy the access token, API key, and secret key and paste them into the &quot;seller sync app configuration&quot; on their Multi-vendor seller panel</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_14_16-1200x801.png" alt="screenshot-sagar-satti-store.myshopify.com-2022.02.09-12_14_16"></p><p>NOTE: Ignore the flow explained below as the private apps are now depreciated by Shopify. Please skip to the &quot;<a href="https://webkul.com/blog/seller-shopify-store-connector-multi-vendor-marketplace-for-shopify/#seller-panel" target="_blank" rel="noopener noreferrer">seller panel</a>&quot; section below</p><p>To make the product sync features work, the sellers first need to create a private app on their respective Shopify stores.</p><p>Then, the sellers will get all the app details to configure for syncing products with the admin’s store.</p><h3 id="how-does-the-seller-create-a-private-app" tabindex="-1"><a class="header-anchor" href="#how-does-the-seller-create-a-private-app"><span>How does the Seller Create a Private App?</span></a></h3><p>To create a Private App, firstly the seller needs to Visit the “<strong>Apps</strong>” section of his/her Shopify Store.</p><p>Then, scrolling down to the bottom, You will get the “<strong>Manage Private Apps</strong>” option. Click on it to create a new Private app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Shopify-1200x576.png" alt="Seller App"></p><p><a href="https://webkul.com/blog/how-to-create-js-sdk-token/#panel-0" target="_blank" rel="noopener noreferrer"><strong>Know how to create a Private App</strong></a></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/screenshot-rohit-jha-store18.myshopify.com-2021.05.17-17_06_49-1200x549.png" alt="seller shopify store connector"></p><p>This way, the seller can create a private app from his/her Shopify store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/screenshot-rohit-jha-store18.myshopify.com-2021.05.17-17_02_15-1200x549.png" alt="seller shopify store connector API"></p><p>Now, the seller will configure all the details from his seller panel.</p><h3 id="required-permissions-to-create-a-private-app" tabindex="-1"><a class="header-anchor" href="#required-permissions-to-create-a-private-app"><span>REQUIRED PERMISSIONS TO CREATE A PRIVATE APP</span></a></h3><p><strong>Here is the required Permission for private seller_app:</strong></p><p>Assigned fulfillment orders _(<strong>Read and write</strong>)<br> _# read_orders, write_orders</p><p>Fulfillment services _(<strong>Read and write</strong>)<br> _# read_fulfillments, write_fulfillments</p><p>Inventory _(<strong>Read and write</strong>)<br> _# read_inventory, write_inventory</p><p>Locations _(<strong>Read Access</strong>)<br> _# read_locations</p><p>Order Editing _(<strong>Read and write</strong>)<br> _# read_orders, write_orders<br> Allow this permission if you want to sync the order details with the seller store once edited on the merchant&#39;s store, else don&#39;t allow.</p><p>Orders _(<strong>Read and write</strong>)<br> _# read_orders, write_orders</p><p>Products <em><strong>(Read and write)</strong></em><br> # read_products, write_products</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/Screenshot-15-1200x509.png" alt="Admin API"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-16-1200x511-png-1200×511-.png" alt="Screenshot-16-1200x511-png-1200×511-"></p><h3 id="seller-panel" tabindex="-1"><a class="header-anchor" href="#seller-panel"><span>Seller Panel</span></a></h3><p>After Installing the custom app on the seller Shopify store, the seller has got the access token, API key, and secret key which he/she needs to paste in the &quot;seller sync app configuration&quot;.</p><p>Seller panel &gt;&gt; configuration &gt;&gt; seller sync app configurations</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Dashboard-Seller-•-Multivendor-MarketPlace-1200x627.png" alt="Dashboard-Seller-•-Multivendor-MarketPlace"></p><p>Enter the access token, API key, and secret key &gt;&gt; save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-shopify-trunk.webkul.com-2022.02.09-12_36_19-1091x1024.png" alt="screenshot-shopify-trunk.webkul.com-2022.02.09-12_36_19"></p><p>After saving the details, the seller can now start with importing the products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/02/screenshot-shopify-trunk.webkul.com-2022.02.09-12_44_13-820x1024.png" alt="screenshot-shopify-trunk.webkul.com-2022.02.09-12_44_13"></p><h3 id="admin-panel-seller-supported-app-configuration" tabindex="-1"><a class="header-anchor" href="#admin-panel-seller-supported-app-configuration"><span>Admin Panel: Seller Supported App Configuration</span></a></h3><p><strong>Seller App Configuration</strong></p><p>**SYNC ORDERS<br> **You will have a Sync Order option. So, enabling this option will let you choose whether you want to sync order with the seller&#39;s store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Seller-Supported-App-Configuration-Admin-1200x627.png" alt="Seller-Supported-App-Configuration-Admin"></p><p><strong>SYNC ONLY PAID ORDERS</strong></p><p>With this configuration, you can sync only paid orders with the seller&#39;s Shopify store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/download-20-1-1200x515.png" alt="download-20-1"></p><h3 id="create-orders-on-seller-store" tabindex="-1"><a class="header-anchor" href="#create-orders-on-seller-store"><span>Create Orders on Seller Store</span></a></h3><p>You will now have an option to create orders on your seller&#39;s Shopify store.</p><p>For this, Go to Orders&gt;&gt;Order Listing&gt;&gt;View Order&gt;&gt;More Action&gt;&gt;Create Order on Seller Store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/download-21-1-1200x505.png" alt="download-21-1"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/03/download-22-1-1200x503.png" alt="download-22-1"></p><p><strong>Note:-</strong> Even, the admin will get a reference order number like below that will be shown order section of seller&#39;s Shopify store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/02/screenshot_from_2022_12_27_12_51_33-1200x595.png" alt="screenshot_from_2022_12_27_12_51_33"></p><h3 id="manual-sync-orders" tabindex="-1"><a class="header-anchor" href="#manual-sync-orders"><span>Manual Sync Orders</span></a></h3><p>In case an order is placed on the admin&#39;s store and is not synced with the seller&#39;s Shopify store then, then seller can sync the order manually from the seller panel.</p><p>To sync the order manually, the seller need to visit the Multi-vendor <strong>Seller Panel</strong>&gt;&gt;Go to <strong>Orders</strong>&gt;&gt;<strong>View Order</strong>&gt;&gt;On Order Detail Page-In <strong>More Action</strong>-Click <strong>Sync Order</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-15-1200x549.png" alt="download-15"></p><p>This way, orders can be synced manually with the seller Shopify store connector.</p><h3 id="sync-order-refund" tabindex="-1"><a class="header-anchor" href="#sync-order-refund"><span>Sync Order Refund</span></a></h3><p>You can now choose to sync orders from the seller store to the admin store and vice versa. For this, you need to visit the admin panel&gt;&gt;Go to Configuration&gt;&gt;<strong>Seller Supported App Configuration</strong>.</p><p>Enable the below tabs:-<br> ORDERS REFUND FROM SELLER TO ADMIN STORE:- You can choose if you want to sync the seller&#39;s order refunds to your store or not.</p><p>ORDER REFUND FROM ADMIN TO SELLER STORE:- You can choose if you want to sync orders from your store to the seller store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/01/7ed348be-4f35-48bb-b883-d741689b6432-1200x584.png" alt="7ed348be-4f35-48bb-b883-d741689b6432"></p><h3 id="sync-customer-details" tabindex="-1"><a class="header-anchor" href="#sync-customer-details"><span>Sync Customer Details</span></a></h3><p>By enabling this tab, you can sync customer details in order with the seller&#39;s store. Let&#39;s understand this feature in detail.</p><p>CASE 1: Sync Customer Details tab is <strong>ON</strong> (<strong>enabled</strong>):</p><p>Once a customer places an order, the customer is there on the seller&#39;s Shopify store with complete shipping and billing details.</p><p>Also, the customers will receive an email from the seller&#39;s store regarding the same.</p><p>NOTE:- In this case, if you don&#39;t want to send an email to the customer, you can configure a dummy email.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/05/Screenshot-2020-05-08T103054.342-1200x622.png" alt="customer details ON"></p><p>CASE 2: Sync Customer Details tab is <strong>OFF</strong> (<strong>disabled</strong>):</p><p>In case you disable this tab, you will get multiple options to choose whether you want to sync the customer&#39;s shipping address, billing address, name, and email or not.</p><p>You can configure the settings as per the requirements.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/05/Seller_Supported_App_Configuration_Admin-1151x1024.png" alt="seller app configuration"></p><p>**Product Details Configuration<br> **In the “Product Details Configuration”, you can enable/disable the options. Thus, auto-update the enable fields when the sellers make any update from their end.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Seller-Supported-App-Configuration-Admin-1-889x1024.png" alt="Seller-Supported-App-Configuration-Admin-1"></p><h3 id="restrict-image-count-on-products" tabindex="-1"><a class="header-anchor" href="#restrict-image-count-on-products"><span>RESTRICT IMAGE COUNT ON PRODUCTS</span></a></h3><p>Admin can enable restrict image count configuration to restrict the number of Product images between 1 to 20.</p><p>So seller can only sync a certain number of images which is set by the Admin.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/11/bdjsbhdsj-1200x542.png" alt="bdjsbhdsj"></p><h3 id="import-product-meta-field" tabindex="-1"><a class="header-anchor" href="#import-product-meta-field"><span>Import Product Meta Field</span></a></h3><p>You can now import product meta fields from the seller&#39;s Shopify store into your marketplace.</p><p>For this, you need to enable the below-given option from the Seller App Configuration&gt;&gt;<strong>Product Details Configuration</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-5-1200x610.png" alt="Screenshot-5"></p><h3 id="seller-updating-products" tabindex="-1"><a class="header-anchor" href="#seller-updating-products"><span>Seller Updating Products</span></a></h3><p>If the seller has disabled the Auto Sync New Products Tab:-</p><p>Once the seller makes any changes in the products on his/her Shopify store, he/she will get info on the multi-vendor seller dashboard to update all products.</p><p>Now, clicking the “<strong>View the products</strong>” button, redirect your sellers to a page where all the products will be listed that are not yet updated on the admin’s store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Screenshot-100-1200x499.png" alt="Screenshot-100"></p><p>Additionally, the seller can update all the products in a go simply by clicking the**“Update all products”** button. Additionally, the seller can manually update each product as per his/her choice.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace-1200x627.png" alt="Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace"></p><p>In the manual update, Clicking the “Update Product” button, the product will be in the “<strong>Processing</strong>” state.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace-1-1200x627.png" alt="Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace-1"></p><p>Once processed, the product will get unlisted from this section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace-2-1200x627.png" alt="Bulk-Product-Update-Details-Seller-•-Multivendor-MarketPlace-2"></p><p>Now, before the sellers start importing products from their respective Shopify stores into the app, please ask your sellers to firstly**, Map The Products then, Import Products**.</p><h3 id="sales-channel-configuration-seller-panel" tabindex="-1"><a class="header-anchor" href="#sales-channel-configuration-seller-panel"><span>Sales channel configuration : Seller panel</span></a></h3><p>Using this configuration Sellers can import their products by creating a unique sales channel, especially for the Admin Store which is not available on their own online store.</p><p>The seller can create a custom app and provide certain permission which you find below that would convert the custom app into a Sales channel that they can select for their product.</p><p>Please refer to the images below for a better understanding.</p><p>Sellers can add Products only for the Admin marketplace which will only be available on the Sales channel created by the Seller and connected via the seller panel.</p><p><strong>Note: Once Seller enables this configuration they won&#39;t be able to disable it.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/Sales-channel-1200x616.png" alt="Sales-channel"></p><p>To Add the product Please make sure the Product is added to the sales channel app that the Seller created as shown below otherwise it won&#39;t be imported or synced.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/sales-channel-1-1200x856.png" alt="sales-channel-1"></p><p>Pic 1</p><h3 id="required-permission-for-sales-channel-configuration-1" tabindex="-1"><a class="header-anchor" href="#required-permission-for-sales-channel-configuration-1"><span>Required Permission for Sales Channel Configuration</span></a></h3><p>#write_product_listings, #read_product_listings</p><p><strong>Storefront API access scopes</strong>:<br> #<code>unauthenticated_read_product_listings</code></p><p><strong><em>Note: These permissions are mandatory for Sales Channel Configuration.</em></strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/permissions-2.png" alt="permissions-2"></p><p>Pic 2</p><h3 id="map-product-type-and-collection" tabindex="-1"><a class="header-anchor" href="#map-product-type-and-collection"><span>Map Product Type and Collection</span></a></h3><p>The seller will have the option to map the admin’s store product type &amp; collection with the product type &amp; collection of their Shopify store.</p><p>Note:- Make sure that the admin has restricted the product type &amp; collection from the admin panel. Also, add types and collections to the admin&#39;s marketplace.</p><p>Now, on the seller panel, here is the option to map product types &amp; collections in the Seller Sync App Configuration menu of the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Seller-App-Configuration-Details-Seller-•-Multivendor-MarketPlace-1200x619.png" alt="Map Collection"></p><p><strong>MAP COLLECTION</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Map-Collections-•-Multivendor-MarketPlace-1200x619.png" alt="Map-Collections-•-Multivendor-MarketPlace"></p><p><strong>MAP PRODUCT TYPE</strong></p><p>Similarly, sellers can map the product type of their respective stores with the product type of your Shopify store.</p><p>Thus, clicking the Map Type, the seller will have the option to choose once product type from the admin&#39;s store and map the same with the product type of his/her Shopify store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Seller-App-Configuration-Details-Seller-•-Multivendor-MarketPlace-1-1200x619.png" alt="Seller-App-Configuration-Details-Seller-•-Multivendor-MarketPlace-1"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Map-Product-Type-•-Multivendor-MarketPlace-1200x619.png" alt="Map-Product-Type-•-Multivendor-MarketPlace"></p><h3 id="map-product-tags" tabindex="-1"><a class="header-anchor" href="#map-product-tags"><span>Map Product Tags</span></a></h3><p>You can now allow sellers to map the product tags of their respective stores with the product tag of your Shopify store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-ravikant-sh.webkul.com-2021.07.09-13_00_27-1200x549.png" alt="screenshot-ravikant-sh.webkul.com-2021.07.09-13_00_27"></p><p>Clicking Tag Mapping, the seller will get the option to map the tag.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-ravikant-sh.webkul.com-2021.07.09-13_03_34-1200x549.png" alt="screenshot-ravikant-sh.webkul.com-2021.07.09-13_03_34"></p><p>The seller can map product tag via CSV file upload.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-ravikant-sh.webkul.com-2021.07.09-13_04_32-1200x974.png" alt="screenshot-ravikant-sh.webkul.com-2021.07.09-13_04_32"></p><h3 id="seller-wise-product-tag-restriction" tabindex="-1"><a class="header-anchor" href="#seller-wise-product-tag-restriction"><span>Seller-wise product tag restriction</span></a></h3><p>Admin needs to enable this configuration from the <strong>Admin panel &gt; configuration &gt; restrict configuration &gt; enable the restrict product tags tab.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/05/ab1-1200x966.png" alt="seller shopify store connector"></p><p>Once the admin enables this configuration, then the admin can allow or restrict the products tag, <strong>seller wise</strong> at the edit seller section. as shown below.</p><p><strong>Admin panel &gt; seller &gt; seller listing &gt; edit seller.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/05/ab2-1200x619.png" alt="seller shopify store connector"></p><p>If the above configuration is enabled then the seller needs to do mapping but if the admin disables this tab,</p><p>it means the admin allows the seller to import the product along with their product tag.</p><p>The seller will not be able to see the tag mapping option at the time of importing the products if the above tab is disabled.</p><h3 id="import-products-from-seller-s-shopify-store" tabindex="-1"><a class="header-anchor" href="#import-products-from-seller-s-shopify-store"><span>Import Products from Seller’s Shopify Store</span></a></h3><p>Now, by clicking on the Import Products button, the seller can import products from his/her Shopify store to the admin’s Shopify store.</p><p>Seller will have three methods to import products:-</p><p><strong>Method 1:-</strong> Choose a Date Range &amp; import products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Import-Product-From-Seller-App-Seller-•-Multivendor-MarketPlace-1200x459.png" alt="Import-Product-From-Seller-App-Seller-•-Multivendor-MarketPlace"></p><p><strong>2nd Method:-</strong> Import products by comma-separated product IDs.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Screenshot-98-1200x236.png" alt="Screenshot-98"></p><p><strong>Method 3:-</strong> Import products by product handle.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Screenshot-99-1200x252.png" alt="Screenshot-99"></p><p>This way, sellers can import products to the admin’s store.</p><p>Thus, all the products imported by the seller will be visible in the “Product Listing” section of his/her seller panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Product-Seller-•-Multivendor-MarketPlace-1200x627.png" alt="Product-Seller-•-Multivendor-MarketPlace"></p><p>Now, the admin can view a new menu added under the <strong>Configuration</strong> menu of the admin panel i.e. <strong>Seller Supported App Configuration</strong>.</p><h3 id="inventory-update-on-order-points-to-be-noted" tabindex="-1"><a class="header-anchor" href="#inventory-update-on-order-points-to-be-noted"><span>Inventory Update on Order: Points to be Noted!</span></a></h3><p><strong>ORDER CREATION ON ADMIN&#39;S STORE</strong></p><p>Case 1: Sync Order tab is <strong>OFF</strong></p><p>When the order is placed on the admin&#39;s store and <strong>Sync Order</strong> Tab is disabled then, Order will not create on the seller&#39;s Shopify store. However inventory will be managed on the seller&#39;s store.</p><p>Case 2: Sync Order tab is <strong>ON</strong></p><p>Once an order is placed on the admin&#39;s store and <strong>Sync Order</strong> Tab is ON then, the same order will be created on the seller&#39;s Shopify store too.</p><p>Thus, update inventory and manage product quantity accordingly on the seller&#39;s store.</p><p>Merchants don&#39;t need to update the inventory each time when an order is placed on the admin&#39;s Shopify store.</p><p><strong>ORDER CREATION ON SELLER&#39;S STORE</strong></p><p>Once an order is placed on the seller&#39;s Shopify store, only product inventory will be managed on the admin end i.e. product quantity gets updated on the admin&#39;s store.</p><p>In case any seller&#39;s product (listed on the admin&#39;s store) is not synced with the seller&#39;s store then,</p><p>both the admin and the seller can sync products manually from the <strong>Product Listing</strong> section of their respective panels.</p><p><strong>Admin End</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Product-Admin-1200x619.png" alt="admin end- product "></p><p><strong>Seller End</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Product-Seller-•-Multivendor-MarketPlace-1-1200x619.png" alt="seller end"></p><h3 id="third-party-app-for-drop-shipping" tabindex="-1"><a class="header-anchor" href="#third-party-app-for-drop-shipping"><span>Third-Party App for Drop Shipping</span></a></h3><p>In case any of your sellers are using a third-party app, Oberlo for drop shipping then,</p><p>products synced from Oberlo to seller’s Shopify store can easily be synced with the admin’s store at his store’s primary location.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Screenshot-54.png" alt="Multivendor Marketplace App for Shopify- Seller Product Sync"></p><p>To import products from Oberlo to the seller app, the seller needs to enable the “<strong>Third-Party App for Drop Shipping</strong>” option from the <strong>Configuration</strong> menu.</p><p>Moreover, once enable, import products to the seller app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Seller-App-Configuration-Details-Seller-•-Multivendor-MarketPlace-2-1200x627.png" alt="Seller-App-Configuration-Details-Seller-•-Multivendor-MarketPlace-2"></p><p>Get the list of all imported products in the Products section of the seller app (sync with the admin&#39;s store).</p><p>This way, products will update on the admin’s marketplace.</p><h3 id="connector-price-rule-currency-conversion" tabindex="-1"><a class="header-anchor" href="#connector-price-rule-currency-conversion"><span>Connector Price Rule &amp; Currency Conversion</span></a></h3><p>Seller will select the Seller Sync App from the drop-down menu for currency conversion &amp; price rule:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Screenshot22-1200x528.png" alt="Screenshot22"></p><p><strong>CURRENCY CONVERSION</strong></p><p>If the currency of your seller’s store is different from the currency you set on your marketplace, then, the sellers can specify their currency rate with respect to your currency rate.</p><p>Accordingly, your seller’s product price calculates once a customer places an order</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Price-Rule-Seller-•-Multivendor-MarketPlace-1-1200x825.png" alt="Price-Rule-Seller-•-Multivendor-MarketPlace-1"></p><p><strong>PRICE RULE</strong></p><p>In the price rule menu, the seller can create a price rule to manage the price of the product on your Shopify store. The seller has to set the price rule:</p><ul><li>The seller has to enable or disable the price rule status to configure the settings.</li><li>Select the price rule, either to increase or decrease.</li><li>Select the Price change, either fixed or percentage.<br> Enter the amount of how much the sellers want to increase or decrease the price.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Price-Rule-Seller-•-Multivendor-MarketPlace-2-1200x627.png" alt="Price-Rule-Seller-•-Multivendor-MarketPlace-2"></p><h3 id="allow-sellers-to-register-webhook" tabindex="-1"><a class="header-anchor" href="#allow-sellers-to-register-webhook"><span>Allow Sellers to Register Webhook</span></a></h3><p><strong>PURPOSE</strong>:- The seller requires certain <a href="https://webkul.com/blog/seller-shopify-store-connector-multi-vendor-marketplace-for-shopify/#required-permissions-to-create-a-private-app" target="_blank" rel="noopener noreferrer">permission</a> to create a private app to make the sync process work.</p><p>In case the seller has missed enabling any permission and created the private app, still, he/she will have the option to register webhooks from his/her seller panel.</p><p>The seller can visit the <strong>Seller Sync App Configuration</strong> where there is a list of all the webhooks. Just register/unregister webhooks as per the requirement.</p><p>Using the seller store connector, the admin can now allow sellers to view/register webhooks from the seller panels based on the permission provided.</p><p>Seller Panel&gt;&gt;Seller Sync App Configuration&gt;&gt;Click <strong>Shopify Webhooks</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/05/Seller_App_Configuration_Details_Seller_•_Multivendor_MarketPlace-1-1158x1024.png" alt="register webhook"></p><p>List of all webhooks. The seller can anytime unregister webhooks from the listing.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/05/Screenshot-2020-05-15T204027.688-1200x585.png" alt="unregister"></p><p>The seller can unregister/delete webhook and can anytime register it again.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/05/Screenshot-2020-05-15T204208.729-1200x586.png" alt="delete webhook"></p><h3 id="map-product-with-connected-stores" tabindex="-1"><a class="header-anchor" href="#map-product-with-connected-stores"><span>Map Product With Connected Stores</span></a></h3><p>Sellers can now map products with their connected Shopify stores.</p><p>In case a seller wants to map a product with a specific product of his/her Shopify store then, the variant will be mapped automatically.</p><p>Now, the seller can map the products from the Product Listing&gt;&gt;Edit product&gt;&gt;<strong>Map Product</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Edit-Product-Seller-•-Multivendor-MarketPlace-1-1200x597.png" alt="Edit-Product-Seller-•-Multivendor-MarketPlace-1"></p><p>Clicking the Map Product button, the seller can choose whether to map the products manually or auto-map with any specific product with same SKU or Option Name.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Screenshot-2020-10-09T172100.279-1200x592.png" alt="Screenshot-2020-10-09T172100.279"></p><p><strong>On selecting the &quot;Map Product Automatic&quot; option</strong>:- The seller needs to choose a product from his/her Shopify store and then, choose the Map Type as &quot;Map with SKUs&quot; or &quot;Map with Option Name&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Screenshot20-2-1200x563.png" alt="Screenshot20-2"></p><p><strong>On selecting &quot;Map Product Manually&quot; option</strong>:-</p><p>Once you choose this option, the seller simply needs to select his/her Shopify store product with which you need to map the seller&#39;s marketplace product.click the <strong>Submit</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Screenshot-2020-10-09T173753.254-1200x510.png" alt="Screenshot-2020-10-09T173753.254"></p><h3 id="sync-order-on-seller-shopify-store" tabindex="-1"><a class="header-anchor" href="#sync-order-on-seller-shopify-store"><span>Sync Order On Seller Shopify Store</span></a></h3><p>In case the order created in the app, not synced with the seller&#39;s Shopify store then, the seller can manually create an order on his/her Shopify store.</p><p>For this, the seller will visit the seller panel&gt;&gt;Order&gt;&gt;Edit Order&gt;&gt;Click the <strong>&quot;Sync Order&quot;</strong> button in the More Action menu.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/12/Order-Details-Seller-•-Multivendor-MarketPlace-6-1200x597.png" alt="Order-Details-Seller-•-Multivendor-MarketPlace-6"></p><h3 id="update-marketplace-shipping-labels" tabindex="-1"><a class="header-anchor" href="#update-marketplace-shipping-labels"><span>Update Marketplace Shipping Labels</span></a></h3><p>You can now allow sellers to change the marketplace shipping labels to their respective Shopify store&#39;s shipping labels.</p><p>For this, visit the Seller Supported App Configuration &amp; enable the tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Seller-Supported-App-Configuration-Admin-1-1200x516.png" alt="Seller-Supported-App-Configuration-Admin-1"></p><p>SELLER PANEL</p><p>The seller can enable the option from the Seller Sync App Configuration menu:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/08/Screenshot-2021-08-20T134736.976.png" alt="Screenshot-2021-08-20T134736.976"></p><h3 id="multi-location-inventory-sync" tabindex="-1"><a class="header-anchor" href="#multi-location-inventory-sync"><span>Multi-location Inventory Sync</span></a></h3><p>In case you are using the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-multi-location-inventory/" target="_blank" rel="noopener noreferrer">Multi-location Inventory feature app</a> along with this connector add-on:-</p><p>You can provide an option to let sellers choose the location of which they want to sync the product quantity with your Shopify store.</p><p>There will be a list of the seller&#39;s Shopify store locations (seller&#39;s Shopify-admin) once you enable the tab.<br> For this, Go to Multi-vendor <strong>Seller Panel</strong>&gt;&gt;<strong>Configuration</strong>&gt;&gt;<strong>Seller Sync App Configuration</strong>.</p><p>Now, sellers can enable the location on the seller panel and sync the product&#39;s quantity with the admin&#39;s marketplace.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/screenshot-vineet-sinha-sh.webkul.com-2021.10.08-16_07_56-1200x590.png" alt="Seller end"></p><h3 id="inventory-policy-sync" tabindex="-1"><a class="header-anchor" href="#inventory-policy-sync"><span>Inventory Policy Sync</span></a></h3><p>With this option, you can now verify the &quot;Continue Selling Out of Stock&quot; option on Shopify and allow customers to purchase the items accordingly.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/Screenshot-2021-10-08T180822.481-1200x472.png" alt="Screenshot-2021-10-08T180822.481"></p><p>Now, to enable this tab, go to admin panel&gt;&gt;Configuration&gt;&gt;<strong>Seller Supported App Configuration</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/Screenshot-2021-10-08T175408.237-1-1200x532.png" alt="Screenshot-2021-10-08T175408.237-1"></p><p>That&#39;s all about the this feature app.</p>',277)]))}const i=t(s,[["render",l]]),c=JSON.parse('{"path":"/classic/Featured-App/Connector/SELLER%20SHOPIFY%20STORE%20CONNECTOR.html","title":"SELLER SHOPIFY STORE CONNECTOR","lang":"en-US","frontmatter":{"title":"SELLER SHOPIFY STORE CONNECTOR","description":"SELLER SHOPIFY STORE CONNECTOR","date":"2025-07-20T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Features","slug":"features","link":"#features","children":[]},{"level":3,"title":"Activate the Feature App","slug":"activate-the-feature-app","link":"#activate-the-feature-app","children":[]},{"level":3,"title":"NEW WORKFLOW :","slug":"new-workflow","link":"#new-workflow","children":[]},{"level":3,"title":"REQUIRED PERMISSIONS FOR CUSTOM APP","slug":"required-permissions-for-custom-app","link":"#required-permissions-for-custom-app","children":[]},{"level":3,"title":"Required Permission for Sales Channel Configuration","slug":"required-permission-for-sales-channel-configuration","link":"#required-permission-for-sales-channel-configuration","children":[]},{"level":3,"title":"How does the Seller Create a Private App?","slug":"how-does-the-seller-create-a-private-app","link":"#how-does-the-seller-create-a-private-app","children":[]},{"level":3,"title":"REQUIRED PERMISSIONS TO CREATE A PRIVATE APP","slug":"required-permissions-to-create-a-private-app","link":"#required-permissions-to-create-a-private-app","children":[]},{"level":3,"title":"Seller Panel","slug":"seller-panel","link":"#seller-panel","children":[]},{"level":3,"title":"Admin Panel: Seller Supported App Configuration","slug":"admin-panel-seller-supported-app-configuration","link":"#admin-panel-seller-supported-app-configuration","children":[]},{"level":3,"title":"Create Orders on Seller Store","slug":"create-orders-on-seller-store","link":"#create-orders-on-seller-store","children":[]},{"level":3,"title":"Manual Sync Orders","slug":"manual-sync-orders","link":"#manual-sync-orders","children":[]},{"level":3,"title":"Sync Order Refund","slug":"sync-order-refund","link":"#sync-order-refund","children":[]},{"level":3,"title":"Sync Customer Details","slug":"sync-customer-details","link":"#sync-customer-details","children":[]},{"level":3,"title":"RESTRICT IMAGE COUNT ON PRODUCTS","slug":"restrict-image-count-on-products","link":"#restrict-image-count-on-products","children":[]},{"level":3,"title":"Import Product Meta Field","slug":"import-product-meta-field","link":"#import-product-meta-field","children":[]},{"level":3,"title":"Seller Updating Products","slug":"seller-updating-products","link":"#seller-updating-products","children":[]},{"level":3,"title":"Sales channel configuration : Seller panel","slug":"sales-channel-configuration-seller-panel","link":"#sales-channel-configuration-seller-panel","children":[]},{"level":3,"title":"Required Permission for Sales Channel Configuration","slug":"required-permission-for-sales-channel-configuration-1","link":"#required-permission-for-sales-channel-configuration-1","children":[]},{"level":3,"title":"Map Product Type and Collection","slug":"map-product-type-and-collection","link":"#map-product-type-and-collection","children":[]},{"level":3,"title":"Map Product Tags","slug":"map-product-tags","link":"#map-product-tags","children":[]},{"level":3,"title":"Seller-wise product tag restriction","slug":"seller-wise-product-tag-restriction","link":"#seller-wise-product-tag-restriction","children":[]},{"level":3,"title":"Import Products from Seller’s Shopify Store","slug":"import-products-from-seller-s-shopify-store","link":"#import-products-from-seller-s-shopify-store","children":[]},{"level":3,"title":"Inventory Update on Order: Points to be Noted!","slug":"inventory-update-on-order-points-to-be-noted","link":"#inventory-update-on-order-points-to-be-noted","children":[]},{"level":3,"title":"Third-Party App for Drop Shipping","slug":"third-party-app-for-drop-shipping","link":"#third-party-app-for-drop-shipping","children":[]},{"level":3,"title":"Connector Price Rule & Currency Conversion","slug":"connector-price-rule-currency-conversion","link":"#connector-price-rule-currency-conversion","children":[]},{"level":3,"title":"Allow Sellers to Register Webhook","slug":"allow-sellers-to-register-webhook","link":"#allow-sellers-to-register-webhook","children":[]},{"level":3,"title":"Map Product With Connected Stores","slug":"map-product-with-connected-stores","link":"#map-product-with-connected-stores","children":[]},{"level":3,"title":"Sync Order On Seller Shopify Store","slug":"sync-order-on-seller-shopify-store","link":"#sync-order-on-seller-shopify-store","children":[]},{"level":3,"title":"Update Marketplace Shipping Labels","slug":"update-marketplace-shipping-labels","link":"#update-marketplace-shipping-labels","children":[]},{"level":3,"title":"Multi-location Inventory Sync","slug":"multi-location-inventory-sync","link":"#multi-location-inventory-sync","children":[]},{"level":3,"title":"Inventory Policy Sync","slug":"inventory-policy-sync","link":"#inventory-policy-sync","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/Featured-App/Connector/SELLER SHOPIFY STORE CONNECTOR.md"}');export{i as comp,c as data};
